function translateString(source,lang){if(lang==='vi')return source;const lead=(source.match(/^\s*/)||[''])[0],trail=(source.match(/\s*$/)||[''])[0],s=source.trim();if(!s)return source;const exact=D[s]?.[lang];const pat=patternTranslate(s,lang);return lead+(exact||pat||s)+trail;}
