function renderModal(){let modal=document.getElementById('tk28-language-modal');if(!modal){modal=document.createElement('div');modal.id='tk28-language-modal';modal.className='tk28-language-modal tk28-hidden';modal.setAttribute('data-tk28-no-translate','1');modal.innerHTML='<div class="tk28-language-box" role="dialog" aria-modal="true"><div class="tk28-language-brand"><span>🌐</span><h2 id="tk28-language-title"></h2></div><p id="tk28-language-sub" class="tk28-language-sub"></p><div id="tk28-language-options" class="tk28-language-options"></div><p id="tk28-language-note" class="tk28-language-note"></p></div>';document.body.appendChild(modal);}const c=modalCopy(current);modal.querySelector('#tk28-language-title').textContent=c.title;modal.querySelector('#tk28-language-sub').textContent=c.sub;modal.querySelector('#tk28-language-note').textContent=c.note;const opts=modal.querySelector('#tk28-language-options');opts.innerHTML=SUPPORTED.map(l=>`<button type="button" class="tk28-lang-option ${l===current?'tk28-active':''}" data-lang="${l}"><span class="flag">${META[l].flag}</span><span>${META[l].name}<small>${META[l].native}</small></span></button>`).join('');opts.querySelectorAll('[data-lang]').forEach(b=>b.onclick=()=>{applyLanguage(b.dataset.lang,true);modal.classList.add('tk28-hidden');});return modal;}
