function install(){if(window.TopkeyUpgrade29?.installed)return;const saved=normalizeLang((()=>{try{return localStorage.getItem(KEY)||'vi';}catch{return'vi';}})());current=saved;const launcher=document.createElement('button');launcher.type='button';launcher.id='tk28-language-launcher';launcher.className='tk28-language-launcher';launcher.setAttribute('data-tk28-no-translate','1');launcher.setAttribute('aria-label','Language');launcher.onclick=openModal;document.body.appendChild(launcher);applyLanguage(saved,false);observe();const nativeConfirm=window.confirm.bind(window),nativeAlert=window.alert.bind(window),nativePrompt=window.prompt.bind(window);window.confirm=(msg)=>nativeConfirm(translateString(String(msg??''),current));window.alert=(msg)=>nativeAlert(translateString(String(msg??''),current));window.prompt=(msg,def)=>nativePrompt(translateString(String(msg??''),current),def);const shouldPrompt=isHubEntry()||isSpectatorEntry();if(shouldPrompt)setTimeout(openModal,80);window.addEventListener('hashchange',()=>{if(isSpectatorEntry())setTimeout(openModal,30);});window.TopkeyUpgrade29={installed:true,get language(){return current;},setLanguage:applyLanguage,openLanguagePicker:openModal,translate:(s,l=current)=>translateString(String(s??''),normalizeLang(l)),mode:shouldPrompt?(isHubEntry()?'hub':'spectator'):'inherit'};window.TopkeyI18n=window.TopkeyUpgrade29;}
